import { HealthOmicsRegionRates } from './healthomics-price-list';

const HEADER = [
  '// Generated by `pnpm run generate:healthomics-rates` in packages/shared-lib from AWS',
  "// HealthOmics public price list. Don't edit by hand: rerun the script.",
];

const byKey = <T>(record: Record<string, T>): [string, T][] =>
  Object.entries(record).sort(([a], [b]) => a.localeCompare(b));

// Matches .prettierrc.json, so the generated file passes lint without a reformat.
const PRINT_WIDTH = 120;

function renderSourceUrl(sourceUrl: string): string[] {
  const oneLine = `    sourceUrl: '${sourceUrl}',`;
  return oneLine.length <= PRINT_WIDTH ? [oneLine] : ['    sourceUrl:', `      '${sourceUrl}',`];
}

/**
 * Renders the rate table module. Output is sorted and carries no timestamp of
 * its own, so rerunning the script with unchanged prices produces no diff.
 */
export function renderHealthOmicsRatesModule(ratesByRegion: Record<string, HealthOmicsRegionRates>): string {
  const lines = [
    ...HEADER,
    "import { HealthOmicsRegionRates } from './healthomics-price-list';",
    '',
    'export const HEALTHOMICS_RATES_BY_REGION: Record<string, HealthOmicsRegionRates> = {',
  ];

  for (const [region, rates] of byKey(ratesByRegion)) {
    lines.push(`  '${region}': {`);
    lines.push(`    publicationDate: '${rates.publicationDate}',`);
    lines.push(...renderSourceUrl(rates.sourceUrl));
    lines.push('    instanceHourlyUsd: {');
    for (const [instanceType, usd] of byKey(rates.instanceHourlyUsd)) {
      lines.push(`      '${instanceType}': ${usd},`);
    }
    lines.push('    },');
    lines.push('    runStorageGbHourUsd: {');
    lines.push(`      STATIC: ${rates.runStorageGbHourUsd.STATIC},`);
    lines.push(`      DYNAMIC: ${rates.runStorageGbHourUsd.DYNAMIC},`);
    lines.push('    },');
    lines.push('  },');
  }

  lines.push('};', '');
  return lines.join('\n');
}
